// Wisp Atlas: folktales as stars above the places they were told.
// data/map.json and data/tales/<id>.json are generated by scripts/build-data.js
// from the trilogy Annotated Folktales; data/land.json holds Natural Earth land outlines.

(async function () {
  const $ = (sel) => document.querySelector(sel);
  const listEl = $('#list');
  const searchEl = $('#search');
  const typeEl = $('#type');
  const PAGE_SIZE = 150;
  const WORLD = L.latLngBounds([-50, -170], [80, 192]);
  const LAND_STYLE = { color: '#4A5AA8', weight: 1, dashArray: '2 4', fillColor: '#0E1535', fillOpacity: 1, interactive: false };

  drawSky($('#sky'));

  const [data, land] = await Promise.all([
    fetch('data/map.json').then((r) => r.json()),
    fetch('data/land.json').then((r) => r.json()),
  ]);

  const kinds = data.kinds;
  const typeName = (atu) => data.types[atu]?.[0] ?? 'Unknown type';
  const places = data.places.map((p) => ({
    ...p,
    tales: p.tales.map(([id, title, atu, excerpt]) => ({
      id,
      title,
      atu,
      excerpt,
      placeId: p.id,
      kind: data.types[atu]?.[1] ?? null,
      search: `${title} ${excerpt} ${typeName(atu)} ${p.name}`.toLowerCase(),
    })),
  }));
  const placeById = new Map(places.map((p) => [p.id, p]));
  const allTales = places.flatMap((p) => p.tales);
  const taleById = new Map(allTales.map((t) => [t.id, t]));
  const talesByType = new Map();
  for (const t of allTales) {
    if (!talesByType.has(t.atu)) talesByType.set(t.atu, []);
    talesByType.get(t.atu).push(t);
  }

  for (const [atu, list] of [...talesByType].filter(([, l]) => l.length > 1).sort((a, b) => b[1].length - a[1].length)) {
    typeEl.add(new Option(`${typeName(atu)} · ATU ${atu} (${list.length})`, atu));
  }

  // ---------- State ----------

  const state = { kind: null, place: null, open: null, limit: PAGE_SIZE };
  let matches = new Map(); // place id -> tales matching kind + search + type

  // ---------- Map ----------

  const map = L.map('map', { crs: L.CRS.EPSG4326, zoomControl: false, zoomSnap: 0.1, maxZoom: 7, maxBounds: WORLD.pad(0.3) });
  map.attributionControl.setPrefix('<a href="https://leafletjs.com">Leaflet</a>');
  map.fitBounds(WORLD);
  const updateMinZoom = () => map.setMinZoom(map.getBoundsZoom(WORLD) - 0.3);
  updateMinZoom();
  window.addEventListener('resize', updateMinZoom);

  // Graticule: faint dotted meridians.
  const grid = [];
  for (let lng = -150; lng <= 180; lng += 30) grid.push([[-58, lng], [84, lng]]);
  L.polyline(grid, { color: '#3A4680', weight: 1, opacity: 0.35, dashArray: '1 6', interactive: false }).addTo(map);

  // Land outlines (Antarctica left out; Chukotka unwrapped past 180°, see scripts/build-land.js).
  L.geoJSON(land, { style: LAND_STYLE, attribution: 'Land: <a href="https://www.naturalearthdata.com">Natural Earth</a>' }).addTo(map);

  const constellation = L.layerGroup().addTo(map);
  const brightness = (n) => Math.min(1.9, 0.75 + Math.sqrt(n) / 9);

  const markers = new Map(
    places.map((p, i) => {
      const marker = L.marker([p.lat, p.lng], {
        icon: L.divIcon({
          className: 'star-icon',
          iconSize: [44, 44],
          html: `<span class="star"><span class="ring"></span><span class="ray"></span><span class="ray v"></span><span class="core" style="animation-delay:-${((i * 0.73) % 3.4).toFixed(2)}s"></span><span class="wl"></span></span>`,
        }),
        keyboard: true,
        riseOnHover: true,
      });
      marker.on('click', () => selectPlace(p.id, { pan: false }));
      marker.on('add', () => {
        const el = marker.getElement();
        el.setAttribute('role', 'button');
        el.querySelector('.wl').textContent = p.name;
      });
      return [p.id, marker];
    }),
  );

  // Zoomed in, name the brightest stars; zoomed further, name them all.
  map.on('zoomend', () => {
    map.getContainer().classList.toggle('labels', map.getZoom() >= 3.5);
    map.getContainer().classList.toggle('labels-all', map.getZoom() >= 5);
  });
  $('#zoom-in').addEventListener('click', () => map.zoomIn(0.75));
  $('#zoom-out').addEventListener('click', () => map.zoomOut(0.75));

  // ---------- Filtering ----------

  function applyFilter() {
    const q = searchEl.value.trim().toLowerCase();
    const type = typeEl.value || null;
    matches = new Map();
    for (const p of places) {
      const hits = p.tales.filter((t) => (state.kind === null || t.kind === state.kind) && (!type || t.atu === type) && (!q || t.search.includes(q)));
      matches.set(p.id, hits);
      const marker = markers.get(p.id);
      if (!hits.length && p.id !== state.place) {
        marker.remove();
        continue;
      }
      if (!map.hasLayer(marker)) marker.addTo(map);
      const el = marker.getElement();
      el.querySelector('.star').style.setProperty('--k', brightness(Math.max(hits.length, 1)));
      el.setAttribute('aria-label', `${p.name}: ${hits.length} ${hits.length === 1 ? 'tale' : 'tales'}`);
      el.classList.toggle('on', p.id === state.place);
      el.classList.toggle('major', hits.length >= 20);
    }
    drawConstellation();
    render();
  }

  // Join the places that share a tale type: from the open tale's star, or across a chosen type.
  function drawConstellation() {
    constellation.clearLayers();
    for (const m of markers.values()) m.getElement()?.classList.remove('kin');
    const open = state.open && taleById.get(state.open);
    const atu = open ? open.atu : typeEl.value;
    if (!atu) return;
    const kinPlaces = [...new Set(talesByType.get(atu).map((t) => t.placeId))].map((id) => placeById.get(id));
    if (kinPlaces.length < 2) return;
    const hub = open ? placeById.get(open.placeId) : kinPlaces.sort((a, b) => b.tales.length - a.tales.length)[0];
    for (const p of kinPlaces) {
      if (p !== hub) {
        L.polyline([[hub.lat, hub.lng], [p.lat, p.lng]], { color: '#F4D58D', weight: 1, opacity: 0.55, interactive: false }).addTo(constellation);
      }
      const marker = markers.get(p.id);
      if (!map.hasLayer(marker)) marker.addTo(map);
      marker.getElement().classList.add('kin');
    }
  }

  // ---------- Navigation ----------

  function selectKind(kind) {
    state.kind = kind;
    state.open = null;
    state.limit = PAGE_SIZE;
    applyFilter();
    listEl.scrollTop = 0;
  }

  function selectPlace(id, { pan = true, open = null } = {}) {
    const p = placeById.get(id);
    state.place = p ? id : null;
    state.open = open;
    state.limit = PAGE_SIZE;
    if (p && pan) map.flyTo([p.lat, p.lng], Math.max(map.getZoom(), 3.5), { duration: 0.8 });
    syncHash();
    applyFilter();
    if (open) listEl.querySelector(`[data-tale="${open}"]`)?.scrollIntoView({ block: 'center' });
    else listEl.scrollTop = 0;
  }

  function toggleTale(id) {
    state.open = state.open === id ? null : id;
    syncHash();
    drawConstellation();
    render();
  }

  function syncHash() {
    const hash = state.place ? state.place + (state.open ? `/${state.open}` : '') : '';
    history.replaceState(null, '', hash ? `#${hash}` : location.pathname + location.search);
  }

  function followFallingStar() {
    const pool = places.flatMap((p) => matches.get(p.id) ?? []);
    if (!pool.length) return;
    const t = pool[Math.floor(Math.random() * pool.length)];
    selectPlace(t.placeId, { open: t.id });
    const p = placeById.get(t.placeId);
    map.once('moveend', () => {
      const pt = map.latLngToContainerPoint([p.lat, p.lng]);
      const box = map.getContainer().getBoundingClientRect();
      const meteor = document.createElement('span');
      meteor.className = 'meteor';
      meteor.style.left = `${box.left + pt.x - 140}px`;
      meteor.style.top = `${box.top + pt.y}px`;
      meteor.style.rotate = '25deg';
      document.body.append(meteor);
      meteor.addEventListener('animationend', () => meteor.remove());
    });
  }

  // ---------- Rendering ----------

  const tales = (n) => `${n.toLocaleString()} ${n === 1 ? 'tale' : 'tales'}`;
  const hover = (placeId, on) => markers.get(placeId).getElement()?.classList.toggle('hover', on);

  function render() {
    renderChips();
    renderCrumbs();
    listEl.replaceChildren();

    const place = state.place && placeById.get(state.place);
    const filtering = searchEl.value.trim() || typeEl.value;
    const visible = places.filter((p) => matches.get(p.id).length);
    const total = visible.reduce((n, p) => n + matches.get(p.id).length, 0);

    if (place) {
      const list = matches.get(place.id);
      $('#eyebrow').textContent = place.name;
      $('#count').textContent = tales(list.length);
      renderTales(list, false);
      return;
    }

    $('#eyebrow').textContent = state.kind === null ? 'The whole sky' : kinds[state.kind];
    $('#count').textContent = tales(total);

    if (filtering) {
      renderTales(visible.flatMap((p) => matches.get(p.id)), true);
      return;
    }
    if (!visible.length) {
      listEl.append(el('p', { class: 'empty' }, 'No stars shine here for this search.'));
      return;
    }
    const ul = el('ul');
    for (const p of [...visible].sort((a, b) => matches.get(b.id).length - matches.get(a.id).length)) {
      ul.append(
        el(
          'li',
          {},
          el(
            'button',
            { class: 'row place-row', onclick: () => selectPlace(p.id), onmouseenter: () => hover(p.id, true), onmouseleave: () => hover(p.id, false) },
            el('span', { class: 't' }, p.name),
            el('span', { class: 'n' }, tales(matches.get(p.id).length)),
          ),
        ),
      );
    }
    listEl.append(ul);
  }

  function renderTales(list, showPlace) {
    if (!list.length) {
      listEl.append(el('p', { class: 'empty' }, 'No tales here match this search.'));
      return;
    }
    const ul = el('ul');
    for (const t of list.slice(0, state.limit)) {
      const p = placeById.get(t.placeId);
      const open = t.id === state.open;
      const kin = talesByType.get(t.atu).filter((k) => k !== t);
      const kinPlaces = new Set(kin.map((k) => k.placeId));
      kinPlaces.delete(t.placeId);
      ul.append(
        el(
          'li',
          { class: `tale${open ? ' open' : ''}`, 'data-tale': t.id },
          el(
            'button',
            {
              class: 'row',
              'aria-expanded': String(open),
              onclick: () => toggleTale(t.id),
              onmouseenter: () => hover(t.placeId, true),
              onmouseleave: () => hover(t.placeId, false),
            },
            el('span', { class: 't' }, t.title),
            el('span', { class: 'm' }, showPlace ? `${p.name} · ${typeName(t.atu)}` : typeName(t.atu)),
          ),
          el(
            'div',
            { class: 'tale-body' },
            el('p', {}, t.excerpt),
            el(
              'p',
              { class: 'kin-note' },
              `Tale type ATU ${t.atu}. `,
              !kin.length
                ? 'The only tale of its type here.'
                : kinPlaces.size
                  ? `Its constellation joins ${tales(kin.length)} of the same type from ${kinPlaces.size} other ${kinPlaces.size === 1 ? 'place' : 'places'}.`
                  : `${tales(kin.length)} of the same type come from here too.`,
            ),
            el(
              'div',
              { class: 'actions' },
              el('a', { class: 'btn-gold', href: `#read/${t.id}` }, 'Read the tale'),
              showPlace ? el('button', { class: 'chip', onclick: () => selectPlace(p.id, { open: t.id }) }, 'Show its star') : null,
            ),
          ),
        ),
      );
    }
    listEl.append(ul);
    if (list.length > state.limit) {
      listEl.append(
        el(
          'button',
          {
            class: 'chip more',
            onclick: () => {
              state.limit += PAGE_SIZE;
              render();
            },
          },
          `Show ${Math.min(PAGE_SIZE, list.length - state.limit)} more of ${list.length.toLocaleString()}`,
        ),
      );
    }
  }

  function renderChips() {
    const counts = kinds.map(() => 0);
    for (const t of allTales) if (t.kind !== null) counts[t.kind]++;
    $('#kinds').replaceChildren(
      el('button', { class: `chip${state.kind === null ? ' sel' : ''}`, 'aria-pressed': String(state.kind === null), onclick: () => selectKind(null) }, 'All tales'),
      ...kinds.map((name, i) =>
        el(
          'button',
          { class: `chip${state.kind === i ? ' sel' : ''}`, 'aria-pressed': String(state.kind === i), onclick: () => selectKind(state.kind === i ? null : i) },
          name,
          el('span', { class: 'n' }, counts[i].toLocaleString()),
        ),
      ),
    );
  }

  function renderCrumbs() {
    const place = state.place && placeById.get(state.place);
    const parts = [place ? el('button', { onclick: () => selectPlace(null) }, 'The whole sky') : el('span', { class: 'here' }, 'The whole sky')];
    if (place) parts.push(el('span', { class: 'sep', 'aria-hidden': 'true' }, '›'), el('span', { class: 'here' }, place.name));
    $('#crumbs').replaceChildren(...parts);
  }

  // ---------- Reader ----------

  const reader = $('#reader');
  let readerMap = null;
  let readerStar = null;
  let textSize = 0;
  const TEXT_SIZES = ['', 'large', 'larger'];

  async function openReader(id) {
    const t = taleById.get(id);
    if (!t) return closeReader();
    stopReading();
    const p = placeById.get(t.placeId);
    reader.hidden = false;
    document.body.classList.add('reading');
    reader.focus({ preventScroll: true });
    $('#reader-eyebrow').textContent = `A tale from ${p.name}`;
    $('#reader-title').textContent = t.title;
    $('#reader-place').textContent = p.name;
    $('#reader-text').replaceChildren(el('p', {}, t.excerpt));
    $('#reader-source').textContent = '';
    $('#reader-facts').replaceChildren();
    reader.scrollTop = 0;

    if (!readerMap) {
      readerMap = L.map('reader-map', { crs: L.CRS.EPSG4326, zoomControl: false, attributionControl: false, dragging: false, scrollWheelZoom: false, doubleClickZoom: false, boxZoom: false, keyboard: false, touchZoom: false });
      L.geoJSON(land, { style: LAND_STYLE }).addTo(readerMap);
      readerStar = L.marker([0, 0], { icon: L.divIcon({ className: 'star-icon on', iconSize: [44, 44], html: '<span class="star"><span class="ring"></span><span class="core"></span></span>' }), interactive: false }).addTo(readerMap);
    }
    readerMap.invalidateSize();
    readerMap.setView([p.lat, p.lng], 3);
    readerStar.setLatLng([p.lat, p.lng]);

    const kin = talesByType.get(t.atu).filter((k) => k !== t).sort((a, b) => (a.placeId === t.placeId) - (b.placeId === t.placeId));
    $('#reader-kindred').replaceChildren(...(kin.length ? kin.slice(0, 8).map(storyLink) : [el('li', { class: 'none' }, 'No other tales of this type yet.')]));
    const nearby = p.tales.filter((k) => k !== t && k.atu !== t.atu).slice(0, 4);
    $('#reader-nearby-title').textContent = nearby.length ? `More from ${p.name}` : '';
    $('#reader-nearby').replaceChildren(...nearby.map(storyLink));

    const full = await fetch(`data/tales/${id}.json`).then((r) => r.json());
    if (reader.dataset.tale !== String(id)) return; // another tale was opened meanwhile
    $('#reader-text').replaceChildren(...paragraphs(full.text).map((s) => el('p', {}, s)));
    $('#reader-source').textContent = full.source ? `Source: ${full.source}` : '';
    const facts = [
      ['Tradition', full.provenance],
      ['Tale type', `ATU ${t.atu} · ${typeName(t.atu)}`],
      ['Kind', t.kind === null ? null : kinds[t.kind]],
      ['Notes', full.notes],
    ].filter(([, v]) => v);
    $('#reader-facts').replaceChildren(...facts.flatMap(([k, v]) => [el('dt', {}, k), el('dd', {}, v)]));
    updateProgress();
  }

  function storyLink(t) {
    const p = placeById.get(t.placeId);
    return el('li', {}, el('a', { href: `#read/${t.id}` }, el('span', { class: 't' }, t.title), el('span', { class: 'm' }, p.name)));
  }

  // The texts come without paragraph breaks; group sentences into readable paragraphs.
  function paragraphs(text) {
    const sentences = text.match(/[^.!?]+(?:[.!?]+["'’”)\]]*|$)\s*/g) ?? [text];
    const out = [];
    let cur = '';
    for (const s of sentences) {
      cur += s;
      if (cur.length > 480) out.push(cur.trim()), (cur = '');
    }
    if (cur.trim()) out.push(cur.trim());
    return out;
  }

  function closeReader() {
    stopReading();
    reader.hidden = true;
    delete reader.dataset.tale;
    document.body.classList.remove('reading');
  }

  const updateProgress = () => {
    const max = reader.scrollHeight - reader.clientHeight;
    $('#reader-progress').style.width = `${max > 0 ? (reader.scrollTop / max) * 100 : 100}%`;
  };
  reader.addEventListener('scroll', updateProgress, { passive: true });

  $('#reader-back').addEventListener('click', () => {
    const t = taleById.get(Number(reader.dataset.tale));
    location.hash = t ? `${t.placeId}/${t.id}` : '';
  });
  reader.addEventListener('keydown', (e) => e.key === 'Escape' && $('#reader-back').click());
  $('#reader-size').addEventListener('click', () => {
    textSize = (textSize + 1) % TEXT_SIZES.length;
    $('#reader-text').className = TEXT_SIZES[textSize];
  });

  const aloud = $('#reader-aloud');
  if (!('speechSynthesis' in window)) aloud.hidden = true;
  function stopReading() {
    if ('speechSynthesis' in window) speechSynthesis.cancel();
    aloud.textContent = 'Read aloud';
  }
  aloud.addEventListener('click', () => {
    if (speechSynthesis.speaking) return stopReading();
    const u = new SpeechSynthesisUtterance(`${$('#reader-title').textContent}. ${$('#reader-text').textContent}`);
    u.onend = stopReading;
    speechSynthesis.speak(u);
    aloud.textContent = 'Stop reading';
  });

  // ---------- Events & routing ----------

  let debounce;
  searchEl.addEventListener('input', () => {
    clearTimeout(debounce);
    debounce = setTimeout(() => {
      state.limit = PAGE_SIZE;
      applyFilter();
    }, 150);
  });
  typeEl.addEventListener('change', () => {
    state.limit = PAGE_SIZE;
    state.open = null;
    applyFilter();
    if (typeEl.value) {
      const hits = places.filter((p) => matches.get(p.id).length);
      if (hits.length) map.flyToBounds(L.latLngBounds(hits.map((p) => [p.lat, p.lng])).pad(0.3), { maxZoom: 4, duration: 0.8 });
    }
  });
  $('#falling-star').addEventListener('click', followFallingStar);

  function route() {
    const [a, b] = decodeURIComponent(location.hash.slice(1)).split('/');
    if (a === 'read' && taleById.has(Number(b))) {
      reader.dataset.tale = b;
      openReader(Number(b));
      return;
    }
    closeReader();
    const tale = taleById.get(Number(b));
    if (placeById.has(a)) selectPlace(a, { open: tale && tale.placeId === a ? tale.id : null, pan: state.place !== a });
    else if (state.place || !matches.size) selectPlace(null, { pan: false });
  }
  window.addEventListener('hashchange', route);
  route();

  // ---------- Helpers ----------

  function el(tag, attrs = {}, ...children) {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
      else node.setAttribute(k, v);
    }
    node.append(...children.filter((c) => c != null));
    return node;
  }
})();

// Scatter faint background stars, seeded so the sky looks the same on every visit.
function drawSky(svg) {
  let seed = 7;
  const rand = () => ((seed = (seed * 16807) % 2147483647) - 1) / 2147483646;
  const w = 1600;
  const h = 1000;
  svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
  svg.setAttribute('preserveAspectRatio', 'xMidYMid slice');
  let dots = '';
  for (let i = 0; i < 260; i++) {
    const r = [0.5, 0.6, 0.8, 1, 1.2][Math.floor(rand() * 5)];
    const o = rand() < 0.3 ? 0.7 : 0.35;
    dots += `<circle cx="${(rand() * w).toFixed(1)}" cy="${(rand() * h).toFixed(1)}" r="${r}" fill="#DDE2FF" opacity="${o}"/>`;
  }
  svg.innerHTML = dots;
}
